		/*selectBuyerMpSoNexePopList*/
         SELECT  
                CODE,                 --[0]
                TEXT1                --[1]                
           FROM ICOMCOD2  
          WHERE TYPE = 'Z014'
            AND COMPANY_CODE = #{st_buyer}
            AND CODE = #{st_account_type}
            AND TEXT5 = 'B'

/*selectBuyerMpSoNexeRefNoList*/ SELECT CODE, --[0] REPLACE(TEXT1, '''', '＇') AS TEXT1 --[1] FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = #{st_buyer} AND TEXT4 = #{st_account_type} AND FLAG = 'Y'
AND CODE = #{st_code}
AND TEXT1 LIKE '%' || #{st_text1} || '%'
